from collections import OrderedDict


class LRUCache:
    """get/put cache that evicts the least recently used key when full; get() counts as a use."""

    def __init__(self, capacity):
        self.capacity, self.d = capacity, OrderedDict()

    def get(self, key, default=None):
        if key not in self.d:
            return default
        self.d.move_to_end(key)
        return self.d[key]

    def put(self, key, value):
        self.d[key] = value
        self.d.move_to_end(key)
        if len(self.d) > self.capacity:
            self.d.popitem(last=False)
```

The bug is in the `chunk_windows` function. The current implementation increments `start` by `size` in every iteration, which ignores the `overlap` parameter entirely. To achieve consecutive windows sharing `overlap` tokens, `start` should be incremented by `size - overlap`.

Here is the corrected code:

```python
def chunk_windows(n_tokens, size, overlap):
    """(start, end) token windows of length <= size covering 0..n_tokens, consecutive windows sharing `overlap` tokens;
    the last window ends at n_tokens. Requires 0 <= overlap < size."""
    if not 0 <= overlap < size:
        raise ValueError('need 0 <= overlap < size')
    out, start = [], 0
    while start < n_tokens:
        end = min(start + size, n_tokens)
        out.append((start, end))
        start += size - overlap
    return out
```

The bug is in the `pick_capacity` function. The condition `if b > needed` is incorrect for finding the smallest bucket that can hold the needed tokens. When `needed` is exactly 128, the function should return 128, but it returns 192 because 128 is not greater than 128.

The fix is to change the condition from `b > needed` to `b >= needed`.

```python
def pick_capacity(needed, buckets=(80, 128, 192, 256)):
    """Smallest bucket that can hold `needed` tokens; ValueError if none can."""
    for b in sorted(buckets):
        if b >= needed:
            return b
    raise ValueError(f'{needed} tokens exceed the largest bucket')
